def solve():
    n = int(input())
    commands = input().strip()

    count = 0

    # Check all possible contiguous substrings
    for i in range(n):
        for j in range(i, n):
            # Extract substring from i to j (inclusive)
            substring = commands[i:j+1]

            # Simulate the movement and check if we return to start
            x, y = 0, 0
            for cmd in substring:
                if cmd == 'U':
                    y -= 1
                elif cmd == 'D':
                    y += 1
                elif cmd == 'R':
                    x += 1
                elif cmd == 'L':
                    x -= 1

            # If we return to (0,0), it's a valid substring
            if x == 0 and y == 0:
                count += 1

    return count

